// === Tab: mySketch ===
/*

For #WCCChallenge "Beautiful Burnout"

*/

let crtShader;

//props to whoever made this shader (I think it was an AI, to be fair). I found it in some old source code I had lying around.

const crtShaderSrc = `
precision highp float;

uniform sampler2D tex0;
varying vec2 vTexCoord;

vec2 curveRemapUV(vec2 uv) {
  // as we near the edge of our screen apply greater distortion using a cubic function    
  uv = 2.0 * uv - 1.0;
  vec2 curvature = vec2(16.0); // PI looks good
  vec2 offset = abs(uv.yx) / curvature;
  uv = uv + uv * offset * offset;
  uv = uv * 0.5 + 0.5;
  return uv;
}

vec4 adjBrightness(vec2 inUV, vec4 clr) {
  // clamp((inUV * 1-inUV) * screenResolution/roundness)^vignetteOpacity, 0.0, 1.0)
  float r = 0.5;
  vec2 cornerUV = min(2.0 * (0.5 - abs(inUV - vec2(0.5))) + r, 1.0);
  float br = cornerUV.x * cornerUV.y + 0.15; // clamp(cornerUV.x * cornerUV.y, 0.0, 1.0);
  br = pow(cornerUV.x * cornerUV.y, 2.2) + 0.45; // clamp(cornerUV.x * cornerUV.y, 0.0, 1.0);
  br = clamp(br * br * br * br + 0.55, 0.0, 1.0);
  // br = clamp(pow((inUV *(   )) * 3.1), 1.2), 0.0, 1.0);
  return clr * br;
}

void main() {
  // Get each color channel using coordinates with different amounts
  // of zooms to displace the colors slightly
  // gl_FragColor = vec4(vTexCoord.xy, abs(sin(vTexCoord.x*3.14*10.)), 1.0);

  vec2 remappedUV = curveRemapUV(vTexCoord);
  vec4 baseColor = texture2D(tex0, remappedUV);
  if (remappedUV.x < 0.0 || remappedUV.y < 0.0 || remappedUV.x > 1.0 || remappedUV.y > 1.0){
    gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
  } else {
    gl_FragColor = adjBrightness(vTexCoord, baseColor);
  }

  // gl_FragColor *= abs(sin(remappedUV.x * 720.0));
  gl_FragColor *= abs(sin(remappedUV.y * 576.0));

  // Convert to grayscale luminance
  float lum = dot(gl_FragColor.rgb, vec3(0.299, 0.587, 0.114));

  // Amstrad CPC GT65 green phosphor tint
  vec3 greenPhosphor = vec3(0.2, 1.0, 0.3);

  gl_FragColor.rgb = lum * greenPhosphor;
  gl_FragColor.a = 1.0;
}
`;



function setup() {
  createCanvas(400, 400);
  noFill();
  background(30);
  colorMode(HSL, 360,100,100);
  crtShader = createFilterShader(crtShaderSrc);
	pixelDensity(1);


  //noprotect;
}

function draw() {

  background(30);

  let t = millis()/1000;
  for(let i = 555; i > 0; i--){
    let z = 200+cos(i/24-t*9)*59;
    let x = 0 + 1000 * cos(t);  
    let y = 0 + 1000 * sin(t);

    stroke((i+t)%360, 76,45);

    rect(x,100,(3+sin(t)/2)*i,100)
    rect(100,y,100, (3+sin(t)/2)*i)
    arc(z,z-420,(3+sin(t)/2)*i,(3+sin(t)/2)*i,0,9);

  }

  if (millis() % 10000 >= 5000){
    filter(crtShader);
  }

}

